Suite/Test/Step Name:
PREV_JS = "
	var all = document.querySelectorAll('a, button, span, th, i, div');
	for (var i = 0; i < all.length; i++) {
		var c = all[i]; if (c.offsetParent === null) continue;
		var ng = (((c.getAttribute('ng-click') || '') + ' ' + (c.getAttribute('onclick') || ''))).toLowerCase();
		if (ng.indexOf('prev') !== -1 || ng.indexOf('previous') !== -1 || ng.indexOf('back') !== -1 || ng.indexOf('lastmonth') !== -1) { c.click(); return 'NG_PREV'; }
	}
	var arrows = ['<', '‹', '❮', '◄', '«', '⟨', '←', '〈'];
	for (var i = 0; i < all.length; i++) {
		var c = all[i]; if (c.offsetParent === null) continue;
		if (c.children.length !== 0) continue;
		var t = (c.textContent || '').trim();
		for (var a = 0; a < arrows.length; a++) { if (t === arrows[a]) { c.click(); return 'GLYPH_PREV'; } }
	}
	for (var i = 0; i < all.length; i++) {
		var c = all[i]; if (c.offsetParent === null) continue;
		var cls = ((c.className || '') + '').toLowerCase();
		if (cls.indexOf('prev') !== -1 || cls.indexOf('back') !== -1) { c.click(); return 'CLASS_PREV'; }
		var ic = c.querySelector ? c.querySelector('i, svg') : null;
		var icls = ic ? ((((ic.getAttribute && ic.getAttribute('class')) || (ic.className || '')) + '')).toLowerCase() : '';
		if (icls.indexOf('chevron-left') !== -1 || icls.indexOf('angle-left') !== -1 || icls.indexOf('arrow-left') !== -1 || icls.indexOf('caret-left') !== -1) { c.click(); return 'ICON_PREV'; }
	}
	var months = ['january','february','march','april','may','june','july','august','september','october','november','december'];
	var title = null;
	for (var i = 0; i < all.length; i++) {
		var c = all[i]; if (c.offsetParent === null) continue;
		var t = (c.textContent || '').trim().toLowerCase();
		if (t.length < 25 && t.indexOf('20') !== -1) {
			for (var m = 0; m < 12; m++) { if (t.indexOf(months[m]) !== -1) { title = c; break; } }
		}
		if (title) break;
	}
	if (title) {
		var sib = title.previousElementSibling;
		if (sib && sib.offsetParent !== null) { sib.click(); return 'SIBLING_PREV'; }
		if (title.parentElement) {
			var k = title.parentElement.children;
			if (k.length && k[0] !== title && k[0].offsetParent !== null) { k[0].click(); return 'FIRSTCHILD_PREV'; }
		}
	}
	return 'NO_PREV';
"

BLUE_COUNT_JS = "
	var cells = document.querySelectorAll('div.picker-day');
	var n = 0;
	for (var i = 0; i < cells.length; i++) {
		var d = cells[i]; if (d.offsetParent === null) continue;
		var t = (d.textContent || '').trim();
		if (!(t.length >= 1 && t.length <= 2 && !isNaN(parseInt(t)) && parseInt(t).toString() === t)) continue;
		var bg = window.getComputedStyle(d).backgroundColor || '';
		var s = bg.indexOf('('), e = bg.indexOf(')'); if (s === -1 || e === -1) continue;
		var p = bg.substring(s + 1, e).split(','); if (p.length < 3) continue;
		var r = parseInt(p[0].trim()), g = parseInt(p[1].trim()), b = parseInt(p[2].trim());
		if (!isNaN(r) && !isNaN(g) && !isNaN(b) && b > r + 20 && b > g + 20) { n++; }
	}
	return n;
"

CLICK_BLUE_JS = "
	var cells = document.querySelectorAll('div.picker-day');
	var blues = [];
	for (var i = 0; i < cells.length; i++) {
		var d = cells[i]; if (d.offsetParent === null) continue;
		var t = (d.textContent || '').trim();
		if (!(t.length >= 1 && t.length <= 2 && !isNaN(parseInt(t)) && parseInt(t).toString() === t)) continue;
		var bg = window.getComputedStyle(d).backgroundColor || '';
		var s = bg.indexOf('('), e = bg.indexOf(')'); if (s === -1 || e === -1) continue;
		var p = bg.substring(s + 1, e).split(','); if (p.length < 3) continue;
		var r = parseInt(p[0].trim()), g = parseInt(p[1].trim()), b = parseInt(p[2].trim());
		if (!isNaN(r) && !isNaN(g) && !isNaN(b) && b > r + 20 && b > g + 20) { blues.push(d); }
	}
	var idx = __IDX__;
	if (idx < blues.length) { blues[idx].click(); return JSON.stringify({clicked: true, day: (blues[idx].textContent || '').trim(), total: blues.length}); }
	return JSON.stringify({clicked: false, total: blues.length});
"

READ_PANEL_JS = "
	var allText = document.body.innerText || '';
	var lower = allText.toLowerCase();
	var hidx = lower.indexOf('login record as of');
	var scope = (hidx !== -1) ? lower.substring(hidx, hidx + 1500) : '';
	var hasHeader = hidx !== -1;
	var hasNegative = scope.indexOf('no login history') !== -1 || scope.indexOf('no records') !== -1 || allText.indexOf('이력이 없') !== -1;
	var hasSuccess = scope.indexOf('success') !== -1 || scope.indexOf('성공') !== -1;
	var hasFailure = scope.indexOf('failure') !== -1 || scope.indexOf('failed') !== -1 || scope.indexOf('실패') !== -1;
	var hasRows = hasHeader && !hasNegative && (hasSuccess || hasFailure);
	return JSON.stringify({hasHeader: hasHeader, hasNegative: hasNegative, hasSuccess: hasSuccess, hasFailure: hasFailure, hasRows: hasRows});
"

